function hand(angle,len,w){p.push();p.rotate(angle);p.beginShape();p.vertex(0,-len);p.vertex(w*.35,-len*.75);p.vertex(w*.3,-len*.5);p.vertex(w,-len*.28);p.vertex(w*.35,-len*.12);p.vertex(w*.55,len*.14);p.vertex(0,len*.21);p.vertex(-w*.55,len*.14);p.vertex(-w*.35,-len*.12);p.vertex(-w,-len*.28);p.vertex(-w*.3,-len*.5);p.vertex(-w*.35,-len*.75);p.endShape(p.CLOSE);p.pop()}
p.draw=()=>{const dt=Math.min(p.deltaTime/1000,.08),target=room.confirmed&&(room.face||room.demo);if(target!==room.running){room.running=target;room.rewinding=target?1.8:0;if(target){tone(1046,.9,.16);setTimeout(()=>tone(1568,.8,.08),120)}else{tone(250,.5,.12,45);speakPause()}}room.calm=p.lerp(room.calm,room.running?1:0,.035);let c=room.calm;if(room.rewinding>0){room.seconds-=dt*6;room.rewinding=Math.max(0,room.rewinding-dt)}else if(room.running)room.seconds+=dt;else frozenTime+=dt;clockTime+=dt*(room.gentle?.12:1);document.body.classList.toggle('calm',c>.65);el('state').textContent=(room.demo?'DEMO / ':'')+(room.rewinding>0?'↶ MAKING ROOM':room.running?'● TIME IN MOTION':'● TIME SUSPENDED');el('time-note').textContent=room.running?'PRESENCE CHANGES EVERYTHING':'WAITING FOR REPRESENTATION';let s=Math.floor(room.seconds);el('digital').textContent=[Math.floor(s/3600)%24,Math.floor(s/60)%60,s%60].map(v=>String(v).padStart(2,'0')).join(':');el('elapsed').textContent=String(Math.floor(frozenTime/60)).padStart(2,'0')+':'+String(Math.floor(frozenTime%60)).padStart(2,'0')+' SUSPENDED';if(room.running&&room.rewinding===0&&s!==lastTick){tone(s%2?900:650,.045,.035);lastTick=s}if(audio){hiss.gain.setTargetAtTime(.14*(1-c)+.018*c,audio.currentTime,.2);filter.frequency.setTargetAtTime(1800*(1-c)+220*c,audio.currentTime,.2)}
if(p.frameCount%2===0){p.noiseDetail(c>.5?2:7,.52);field.loadPixels();for(let y=0;y<90;y++)for(let x=0;x<160;x++){let u=x/40,v=y/40,t=clockTime*.13,w=p.noise(u+t,v-t);let n=p.noise(u+2.8*w,v+2.8*p.noise(v,u+t),t);let grain=(Math.random()-.5)*(room.gentle?20:100)*(1-c);let dark=22+n*50+grain;let i=(x+y*160)*4;const palette=[120+115*n,171+70*p.noise(u+2,v+t),165+70*(1-n)];for(let k=0;k<3;k++)field.pixels[i+k]=p.lerp(dark,palette[k],c);if(mask.pixels[i]>128&&n<.35+c*.6)for(let k=0;k<3;k++)field.pixels[i+k]=p.lerp(field.pixels[i+k],30,c);field.pixels[i+3]=255}field.updatePixels()}p.background(15);p.image(field,0,0,p.width,p.height);p.noStroke();p.fill(8,18,27,100*(1-c));p.rect(0,0,p.width,p.height);
// Elaborate astronomical dial: concentric engraved tracks, gears, rosettes and luminous numerals.
p.push();p.translate(p.width*.53,p.height*.43);let R=Math.min(p.width*.36,p.height*.35);p.scale(R/220);p.noStroke();p.fill(5,17,29,175*(1-c)+45);p.circle(0,0,447);if(c<.5)p.blendMode(p.DIFFERENCE);const ink=p.lerpColor(p.color('#b7ceec'),p.color('#47695d'),c);p.stroke(ink);p.noFill();for(const r of [220,217,210,204,178,174,164,158,143,139,99,96,36,30]){p.strokeWeight(r===220?1.5:.6);p.circle(0,0,r*2)}for(let i=0;i<120;i++){p.push();p.rotate(i*p.TWO_PI/120);p.strokeWeight(i%5===0?1.2:.5);p.line(0,-205,0,i%5===0?-192:-200);p.pop()}for(let i=0;i<12;i++){let a=i*p.TWO_PI/12-p.HALF_PI;p.push();p.translate(Math.cos(a)*188,Math.sin(a)*188);p.noStroke();p.fill(ink);p.drawingContext.shadowBlur=room.gentle?3:10;p.drawingContext.shadowColor=c>.5?'#fff4d9':'#9ad4ff';p.textAlign(p.CENTER,p.CENTER);p.textFont('Georgia');p.textSize(i===0?29:23);p.text(roman[i],0,0);p.drawingContext.shadowBlur=0;p.pop();p.push();p.rotate(a);p.strokeWeight(.7);p.beginShape();p.vertex(145,0);p.vertex(159,-7);p.vertex(173,0);p.vertex(159,7);p.endShape(p.CLOSE);p.pop();let gx=Math.cos(a)*119,gy=Math.sin(a)*119;gear(gx,gy,20,12,(i%2?1:-1)*room.seconds*.025);p.noStroke();p.fill(ink);p.textSize(10);p.textAlign(p.CENTER,p.CENTER);p.text(['☉','☽','✧','♁'][i%4],gx,gy)}p.stroke(ink);gear(-42,24,47,22,room.seconds*.03);gear(42,24,47,22,-room.seconds*.03);gear(0,-48,31,18,-room.seconds*.045);gear(0,66,23,14,room.seconds*.06);
p.noFill();p.strokeWeight(.7);p.beginShape();let spiral=Math.max(1,(room.seconds-43060)*.02);for(let a=0;a<Math.min(spiral+12,28);a+=.07){let r=8+a*2.6;p.vertex(Math.cos(a+room.seconds*.01)*r,Math.sin(a+room.seconds*.01)*r)}p.endShape();p.fill(ink);p.strokeWeight(.5);hand(room.seconds/43200*p.TWO_PI,116,10);hand(room.seconds/3600*p.TWO_PI,169,6);p.push();p.rotate(room.seconds/60*p.TWO_PI+(room.running||room.gentle?0:(p.noise(clockTime*3)-.5)*.018));p.strokeWeight(1.3);p.line(0,32,0,-184);p.noFill();p.circle(0,26,13);p.pop();p.noStroke();p.fill(ink);p.circle(0,0,15);p.fill(c>.5?'#dbeac5':'#151c24');p.circle(0,0,6);p.pop();p.blendMode(p.BLEND);
const cc=el('camera-art').getContext('2d'),bc=cameraBuffer.getContext('2d'),video=el('video');if(video.readyState>=2){bc.drawImage(video,0,0,120,75);let pixels=bc.getImageData(0,0,120,75);cc.fillStyle=c>.5?'#d3dfbd':'#19201d';cc.fillRect(0,0,240,150);for(let y=0;y<75;y+=2)for(let x=0;x<120;x+=2){let i=(x+y*120)*4,l=(pixels.data[i]+pixels.data[i+1]+pixels.data[i+2])/765;let fog=Math.random()*(1-c);cc.fillStyle=`rgba(${Math.floor(100+120*c)},${Math.floor(145+65*c)},${Math.floor(130+65*c)},${.15+l*.7})`;cc.beginPath();cc.arc(240-x*2,y*2,Math.max(.5,(1-l)*2+fog*3),0,Math.PI*2);cc.fill()}}else{const im=cc.createImageData(240,150);for(let i=0;i<im.data.length;i+=4){let n=25+Math.random()*45;im.data[i]=n;im.data[i+1]=n+5;im.data[i+2]=n;im.data[i+3]=255}cc.putImageData(im,0,0)}el('camera-label').textContent=room.demo?'SIMULATED PRESENCE':room.face?(c>.5?'VISIBLE. PRESENT. INCLUDED.':'PRESENCE THROUGH THE FOG'):'YOUR PRESENCE, OBSCURED';};
